const id=Number(b.id)||0;const old=id?C.find(x=>String(x.id)===String(id)):null;if(id&&!old)return R(false,{message:'That cost was not found. Refresh the page.'});
const qb=old&&S(old.source)==='QuickBooks';
let row;
if(qb){row={category:S(b.category).slice(0,60)||S(old.category),po_no:S(b.po_no).slice(0,40),notes:S(b.notes).slice(0,1000)};}
else{
 const net=money(b.net),vat=money(b.vat),gross=money(b.gross);
 if(net===null||vat===null||gross===null)return R(false,{message:'Check the amounts - numbers only.'});
 if(net==='')return R(false,{message:'Enter the amount before VAT.'});
 if(!S(b.supplier)&&!S(b.description))return R(false,{message:'Add the supplier or a description.'});
 if(!isD(b.cost_date))return R(false,{message:'Enter the date.'});
 row={job_no:job,cost_date:S(b.cost_date),supplier:S(b.supplier).slice(0,120),ref:S(b.ref).slice(0,60),category:S(b.category).slice(0,60)||'Other',description:S(b.description).slice(0,500),net:net,vat:vat===''?0:vat,gross:gross===''?Math.round((net+(vat===''?0:vat))*100)/100:gross,po_no:S(b.po_no).slice(0,40),notes:S(b.notes).slice(0,1000)};
 if(!id){row.source=S(b.file_name)?'PDF':'Manual';row.qbo_id='';row.file_url='';row.created_by=by;row.created_at=new Date().toLocaleString('sv-SE',{timeZone:'Europe/London'}).replace(' ','T').slice(0,16);}
 if(S(row.ref)&&!b.force){const dup=C.find(x=>String(x.id)!==String(id)&&S(x.ref).toLowerCase()===S(row.ref).toLowerCase()&&S(x.supplier).toLowerCase()===S(row.supplier).toLowerCase());
  if(dup)return R(false,{dup:true,message:'Invoice '+row.ref+' from '+(row.supplier||'this supplier')+' is already on this job ('+S(dup.cost_date)+', £'+Number(dup.net||0).toFixed(2)+'). Save anyway?'});}
}
const data=S(b.file_data).replace(/^data:[^,]*,/,'');const fname=S(b.file_name).replace(/[\\/:*?"<>|#%]+/g,' ').replace(/\s+/g,' ').trim().slice(0,120);
const out={op:'save',id:id,row:row,by:by,job:job,old:old||null,hasFile:false};
if(data&&fname&&!qb){const mime=/\.png$/i.test(fname)?'image/png':(/\.jpe?g$/i.test(fname)?'image/jpeg':'application/pdf');
 const bin=await h.prepareBinaryData(Buffer.from(data,'base64'),fname,mime);out.hasFile=true;
 out.path='CBS System/Operations/Jobs/Job '+job+'/Costs/'+((row.cost_date||'')+' '+(row.supplier||'')+' '+(row.ref||'')).replace(/[\\/:*?"<>|#%]+/g,' ').replace(/\s+/g,' ').trim().slice(0,90)+(/\.[a-z0-9]+$/i.exec(fname)||['.pdf'])[0];
 return [{json:out,binary:{data:bin}}];}
return [{json:out}];

/* Job costs act, step 2: save the cost row (with the SharePoint link when a file was uploaded). */
const h=this.helpers,H='https://old-hub.example/webhook/',K='[redacted-internal-key]';
const S=v=>v==null?'':String(v).trim();
const p=$('Cost Prep').first().json;if(p.op==='done')return [{json:p.reply}];
let url='';if(p.hasFile){try{const u=$('Upload Bill').first().json||{};url=S(u.webUrl);}catch(e){}if(!url)return [{json:{ok:false,message:'Could not save the file to SharePoint. Try again, or save without the file.'}}];}
const now=new Date().toLocaleString('sv-SE',{timeZone:'Europe/London'}).replace(' ','T').slice(0,16);
const stamp=now.slice(8,10)+'/'+now.slice(5,7)+'/'+now.slice(0,4)+' '+now.slice(11,16);
const row=Object.assign({},p.row);if(url)row.file_url=url;
const fmt=v=>'£'+Number(v||0).toFixed(2);
if(p.id){const o=p.old||{};let line='Edited by '+p.by;if(row.net!==undefined&&Number(o.net)!==Number(row.net))line+=' ('+fmt(o.net)+' to '+fmt(row.net)+')';if(row.category&&row.category!==S(o.category))line+=' (category '+(S(o.category)||'none')+' to '+row.category+')';
 row.history=[S(o.history),stamp+' - '+line].filter(Boolean).join(String.fromCharCode(10));
 await h.httpRequest({method:'POST',url:H+'cbs-admin-save?a=save&t=jobcosts&id='+p.id+'&k='+K+'&partial=1',body:row,json:true,timeout:20000});return [{json:{ok:true,id:p.id}}];}
row.history=stamp+' - Added by '+p.by+(url?' from an uploaded bill':'');
const res=await h.httpRequest({method:'POST',url:H+'cbs-admin-save?a=save&t=jobcosts&id=0&k='+K,body:row,json:true,timeout:20000});
return [{json:{ok:true,id:res&&res.id}}];

const b=$input.first().json.body||{};
const data=String(b.data||'').replace(/^data:[^,]*,/,'').replace(/[^A-Za-z0-9+/=]/g,'');
const mime=String(b.mime||'application/pdf').toLowerCase();
if(data.length<200) return [{json:{skip:true}}];
const part=/pdf/.test(mime)?{type:'file',file:{filename:'bill.pdf',file_data:'data:application/pdf;base64,'+data}}:{type:'image_url',image_url:{url:'data:'+(/png/.test(mime)?'image/png':'image/jpeg')+';base64,'+data}};
const prompt=['This is a supplier invoice, bill or receipt sent to Chelmsford Building Services Ltd (UK building contractor).',
'Read it and reply with ONLY a JSON object, no other text, with these keys:',
'supplier: the supplier company that issued it (not Chelmsford Building Services)',
'invoice_no: the invoice / bill / receipt number exactly as printed, or ""',
'date: the invoice date as YYYY-MM-DD (UK source dates are DD/MM/YYYY)',
'po_ref: a purchase order number quoted on it (often "PO", "Your ref", "Order no"), or ""',
'job_ref: a job number of 3 to 6 digits quoted in a job, site, project or reference field, or ""',
'net: total before VAT as a number, or ""',
'vat: VAT amount as a number, or ""',
'gross: total including VAT as a number, or ""',
'category_guess: one of "Materials", "Plant hire", "Subcontractors", "Labour", "Other"',
'description: a short summary of what was supplied (max 12 words)',
'Do not guess values that are not on the document; use "" instead.'].join('\n');
return [{json:{skip:false,req:{model:'anthropic/claude-haiku-4.5',max_tokens:800,temperature:0,messages:[{role:'user',content:[part,{type:'text',text:prompt}]}]}}}];

const r=$input.first().json||{};
if($('Read Prep').first().json.skip===true) return [{json:{ok:false,message:'No file received'}}];
let txt='';try{const c=r.choices&&r.choices[0]&&r.choices[0].message&&r.choices[0].message.content;txt=Array.isArray(c)?c.map(x=>x&&x.text||'').join('\n'):String(c||'');}catch(e){}
const m=txt.match(/\{[\s\S]*\}/);if(!m) return [{json:{ok:false,message:'Could not read the bill'}}];
let o={};try{o=JSON.parse(m[0]);}catch(e){return [{json:{ok:false,message:'Could not read the bill'}}];}
const S=v=>v==null?'':String(v).trim();
const D=v=>{v=S(v);if(/^\d{4}-\d{2}-\d{2}$/.test(v))return v;const x=v.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})$/);if(x){const y=x[3].length===2?'20'+x[3]:x[3];return y+'-'+('0'+x[2]).slice(-2)+'-'+('0'+x[1]).slice(-2);}return '';};
const N=v=>{if(v===''||v==null)return '';const n=parseFloat(String(v).replace(/[^0-9.\-]/g,''));return isNaN(n)?'':Math.round(n*100)/100;};
const job=S(o.job_ref).replace(/[^0-9]/g,'');
return [{json:{ok:true,bill:{supplier:S(o.supplier).slice(0,120),invoice_no:S(o.invoice_no).slice(0,60),date:D(o.date),po_ref:S(o.po_ref).slice(0,40),job_ref:/^\d{3,6}$/.test(job)?job:'',net:N(o.net),vat:N(o.vat),gross:N(o.gross),category_guess:['Materials','Plant hire','Subcontractors','Labour','Other'].indexOf(S(o.category_guess))>-1?S(o.category_guess):'',description:S(o.description).slice(0,200)}}}];

/* Sync QuickBooks button: runs CBS - QuickBooks Sync (cbs-qbo-run). That workflow stays unpublished until a
   QuickBooks Online login is connected in n8n, so until then this records and returns "not connected yet". */
const h=this.helpers,H='https://old-hub.example/webhook/',K='[redacted-internal-key]';
const S=v=>v==null?'':String(v).trim();
let r=null,err='';
try{r=await h.httpRequest({method:'POST',url:H+'cbs-qbo-run',body:{},json:true,timeout:240000});}catch(e){err=String(e.message||e);}
if(r&&typeof r==='object'&&r.ok!==undefined)return [{json:r}];
const msg=/404|not registered|not found/i.test(err)||!err?'QuickBooks is not connected yet.':'The QuickBooks sync did not finish: '+err.slice(0,160);
try{const now=new Date().toLocaleString('sv-SE',{timeZone:'Europe/London'}).replace(' ','T').slice(0,16);
 const L=await h.httpRequest({method:'POST',url:H+'cbs-admin-save?a=list&t=selectopts',body:{},json:true,timeout:30000});
 for(const x of (Array.isArray(L)?L:[]).filter(x=>S(x.reg)==='jobcosts'&&S(x.field)==='qbo_sync'))await h.httpRequest({method:'POST',url:H+'cbs-admin-save?a=del&t=selectopts&id='+x.id+'&k='+K,body:{},json:true,timeout:20000});
 await h.httpRequest({method:'POST',url:H+'cbs-admin-save?a=save&t=selectopts&id=0&k='+K,body:{reg:'jobcosts',field:'qbo_sync',value:JSON.stringify({at:now,ok:false,message:msg}),added_by:'QuickBooks sync'},json:true,timeout:20000});}catch(e){}
return [{json:{ok:false,message:msg}}];
